using System;
using System.Threading;

class Program
{
    static int unsafeCount = 0, safeCount = 0;

    static void Main()
    {
        Thread[] ts = new Thread[4];
        for (int t = 0; t < 4; t++)
        {
            ts[t] = new Thread(() =>
            {
                for (int i = 0; i < 50000; i++)
                {
                    unsafeCount++;                        // read-modify-write: updates can be lost
                    Interlocked.Increment(ref safeCount); // atomic: never loses an update
                }
            });
            ts[t].Start();
        }
        foreach (Thread t in ts) t.Join();
        Console.WriteLine("expected: 200000");
        Console.WriteLine("safe count: " + safeCount);
        // the unsafe total varies from run to run, but it can never exceed the expected value
        Console.WriteLine("unsafe count <= expected: " + (unsafeCount <= 200000));
    }
}

using System;
using System.Threading;

class Program
{
    static readonly object gate = new object(); // private lock object
    static int total = 0;

    static void AddWithLock(int n)
    {
        lock (gate) { total += n; }
    }

    // what the compiler generates for lock(gate) { ... }
    static void AddWithMonitor(int n)
    {
        bool taken = false;
        try
        {
            Monitor.Enter(gate, ref taken);
            total += n;
        }
        finally
        {
            if (taken) Monitor.Exit(gate); // always released, even on exception
        }
    }

    static void Main()
    {
        Thread a = new Thread(() => { for (int i = 0; i < 10000; i++) AddWithLock(1); });
        Thread b = new Thread(() => { for (int i = 0; i < 10000; i++) AddWithMonitor(1); });
        a.Start(); b.Start(); a.Join(); b.Join();
        Console.WriteLine("total = " + total + " (expected 20000)");
        lock (gate) { lock (gate) { Console.WriteLine("reentrant: same thread locked twice"); } }
    }
}

using System;
using System.Threading;

class Account
{
    public readonly int Id;
    public int Balance;
    public Account(int id, int bal) { Id = id; Balance = bal; }
}

class Program
{
    // Always lock the lower Id first: a global order makes circular wait impossible.
    static void Transfer(Account from, Account to, int amount)
    {
        Account first = from.Id < to.Id ? from : to;
        Account second = from.Id < to.Id ? to : from;
        lock (first)
        {
            lock (second)
            {
                from.Balance -= amount;
                to.Balance += amount;
            }
        }
    }

    static void Main()
    {
        Account a = new Account(1, 1000), b = new Account(2, 1000);
        Console.WriteLine("before: " + a.Balance + ", " + b.Balance);
        Thread t1 = new Thread(() => { for (int i = 0; i < 1000; i++) Transfer(a, b, 1); });
        Thread t2 = new Thread(() => { for (int i = 0; i < 1000; i++) Transfer(b, a, 2); });
        t1.Start(); t2.Start(); t1.Join(); t2.Join();
        Console.WriteLine("after:  " + a.Balance + ", " + b.Balance); // no deadlock; total stays 2000
        // Timeout alternative: Monitor.TryEnter(obj, 100) returns false instead of waiting forever.
        object x = new object();
        Console.WriteLine("TryEnter free lock: " + Monitor.TryEnter(x, 100));
    }
}

using System;
using System.Threading;
using System.Threading.Tasks;

class Program
{
    static int maxSeen = 0;
    static int balance = 100, historyCount = 0;
    static readonly object gate = new object();

    // CAS loop: lock-free "store the maximum" on ONE variable
    static void UpdateMax(int value)
    {
        int cur = Volatile.Read(ref maxSeen);
        while (value > cur)
        {
            int seen = Interlocked.CompareExchange(ref maxSeen, value, cur);
            if (seen == cur) break; // our swap won
            cur = seen;             // someone changed it; retry
        }
    }

    static void Main()
    {
        int[] data = { 5, 42, 7, 99, 13, 64, 8, 77 };
        Parallel.ForEach(data, v => UpdateMax(v));
        Console.WriteLine("max = " + maxSeen);

        // Two variables must change together, so a lock is needed
        Parallel.For(0, 1000, i =>
        {
            lock (gate) { balance += 1; historyCount += 1; }
        });
        Console.WriteLine("balance=" + balance + " history=" + historyCount);
    }
}

using System;
using System.Threading;

class Program
{
    // Without volatile the JIT may read 'running' once and loop forever.
    static volatile bool running = true;
    static long iterations = 0;

    static void Main()
    {
        Thread worker = new Thread(() =>
        {
            long n = 0;
            while (running) n++;           // volatile read: sees the update from main
            Interlocked.Exchange(ref iterations, n);
        });
        worker.Start();
        Thread.Sleep(100);
        running = false;                   // volatile write: published to the worker
        worker.Join();
        Console.WriteLine("worker stopped: " + (iterations > 0));

        // Volatile.Read / Write give the same acquire/release guarantees on any field
        int data = 0; bool ready = false;
        Thread producer = new Thread(() => { data = 42; Volatile.Write(ref ready, true); });
        producer.Start();
        while (!Volatile.Read(ref ready)) { }
        Console.WriteLine("data = " + data);  // guaranteed 42
    }
}

using System;
using System.Threading;
using System.Threading.Tasks;

class Program
{
    static SemaphoreSlim slots = new SemaphoreSlim(3); // at most 3 at once
    static int running = 0, maxRunning = 0;

    static async Task Work(int id)
    {
        await slots.WaitAsync();            // does not block a thread while waiting
        try
        {
            int now = Interlocked.Increment(ref running);
            int m;
            while (now > (m = Volatile.Read(ref maxRunning)))
                Interlocked.CompareExchange(ref maxRunning, now, m);
            await Task.Delay(30);           // await is allowed while holding a semaphore
            Interlocked.Decrement(ref running);
        }
        finally { slots.Release(); }
    }

    static void Main()
    {
        Task[] tasks = new Task[10];
        for (int i = 0; i < 10; i++) tasks[i] = Work(i);
        Task.WaitAll(tasks);
        Console.WriteLine("tasks run: 10");
        Console.WriteLine("max concurrent: " + maxRunning + " (limit 3)");
    }
}

using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Threading.Tasks;

class Program
{
    static void Main()
    {
        string[] words = { "a", "b", "a", "c", "b", "a", "a", "c", "d", "a" };
        Console.WriteLine("words: " + string.Join(" ", words));

        ConcurrentDictionary<string, int> counts = new ConcurrentDictionary<string, int>();
        Parallel.ForEach(words, w =>
        {
            // atomic: no ContainsKey-then-indexer race. The delegate may run more than once,
            // so keep it pure.
            counts.AddOrUpdate(w, 1, (key, old) => old + 1);
        });
        foreach (var kv in counts.OrderBy(k => k.Key))
            Console.WriteLine(kv.Key + " = " + kv.Value);

        // GetOrAdd: the value factory can run twice under a race; Lazy makes creation run once
        ConcurrentDictionary<string, Lazy<string>> cache = new ConcurrentDictionary<string, Lazy<string>>();
        string v = cache.GetOrAdd("k", k => new Lazy<string>(() => "expensive-" + k)).Value;
        Console.WriteLine("cached: " + v);
    }
}

using System;
using System.Threading;
using System.Threading.Tasks;

class Program
{
    static void Main()
    {
        int[] data = new int[1000000];
        for (int i = 0; i < data.Length; i++) data[i] = i % 10;

        long seq = 0;
        foreach (int x in data) seq += x;

        // Each thread sums into its own local variable; merge once at the end (no lock per item)
        long total = 0;
        Parallel.For(0, data.Length,
            () => 0L,                                   // thread-local start value
            (i, state, local) => local + data[i],       // no shared writes here
            local => Interlocked.Add(ref total, local)); // merge: once per thread

        Console.WriteLine("sequential: " + seq);
        Console.WriteLine("parallel:   " + total);
        Console.WriteLine("same: " + (seq == total));
        // Tiny bodies like this gain little: scheduling cost rivals the work. Range
        // partitioning (Partitioner.Create) or a plain loop is often as fast.
    }
}

using System;
using System.Threading;
using System.Threading.Tasks;

class Program
{
    static void Main()
    {
        bool onPoolThread = false, onPoolTask = false, onLongRunning = false;

        Thread t = new Thread(() => { onPoolThread = Thread.CurrentThread.IsThreadPoolThread; });
        t.Start(); t.Join();

        Task.Run(() => { onPoolTask = Thread.CurrentThread.IsThreadPoolThread; }).Wait();

        Task.Factory.StartNew(() => { onLongRunning = Thread.CurrentThread.IsThreadPoolThread; },
            TaskCreationOptions.LongRunning).Wait();

        Console.WriteLine("new Thread      on pool: " + onPoolThread);   // dedicated thread
        Console.WriteLine("Task.Run        on pool: " + onPoolTask);     // shared pool thread
        Console.WriteLine("LongRunning     on pool: " + onLongRunning);  // dedicated thread too

        // Tasks return values and carry exceptions, which a raw Thread cannot
        Task<int> sum = Task.Run(() => 40 + 2);
        Console.WriteLine("task result: " + sum.Result);
        try { Task.Run(() => { throw new InvalidOperationException("boom"); }).Wait(); }
        catch (AggregateException e) { Console.WriteLine("caught: " + e.InnerException.Message); }
    }
}

using System;
using System.Text;
using System.Threading;

class Program
{
    static SemaphoreSlim fooTurn = new SemaphoreSlim(1); // one permit: Foo goes first
    static SemaphoreSlim barTurn = new SemaphoreSlim(0);
    static StringBuilder output = new StringBuilder();

    static void Main()
    {
        int n = 5;
        Thread bar = new Thread(() =>   // started first on purpose: order of start must not matter
        {
            for (int i = 0; i < n; i++)
            {
                barTurn.Wait();           // wait until Foo has printed
                output.Append("bar ");
                fooTurn.Release();        // hand the turn back
            }
        });
        Thread foo = new Thread(() =>
        {
            for (int i = 0; i < n; i++)
            {
                fooTurn.Wait();
                output.Append("foo");
                output.Append(' ');
                barTurn.Release();
            }
        });
        bar.Start(); foo.Start();
        foo.Join(); bar.Join();
        Console.WriteLine(output.ToString().Trim());
    }
}

using System;
using System.Threading;

class Program
{
    const int Iter = 2000000;

    static long Run(int stride)
    {
        // stride 1: counters adjacent in memory (same cache line); stride 16: 128 bytes apart
        long[] slots = new long[2 * stride];
        Thread a = new Thread(() => { for (int i = 0; i < Iter; i++) slots[0]++; });
        Thread b = new Thread(() => { for (int i = 0; i < Iter; i++) slots[stride]++; });
        a.Start(); b.Start(); a.Join(); b.Join();
        return slots[0] + slots[stride];
    }

    static void Main()
    {
        long near = Run(1);
        long padded = Run(16);
        Console.WriteLine("adjacent total: " + near);
        Console.WriteLine("padded total:   " + padded);
        // Same result either way; the adjacent version is usually several times slower
        // because both cores keep invalidating one 64-byte cache line.
        // Best fix: each thread uses a local variable and writes it back once at the end.
        long local = 0;
        for (int i = 0; i < Iter; i++) local++;
        Console.WriteLine("local accumulator: " + local);
    }
}

using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

// Immutable snapshot: once built, never changed, so any thread can read it freely.
class Config
{
    public readonly IReadOnlyList<string> Items;
    public Config(IReadOnlyList<string> items) { Items = items; }
}

class Program
{
    static Config current = new Config(new List<string> { "a" });

    // Copy-on-write: build a new object, then publish it with one atomic reference swap.
    static void Add(string item)
    {
        while (true)
        {
            Config old = Volatile.Read(ref current);
            List<string> copy = new List<string>(old.Items);
            copy.Add(item);
            Config next = new Config(copy);
            if (Interlocked.CompareExchange(ref current, next, old) == old) return; // else retry
        }
    }

    static void Main()
    {
        Config before = current;                       // a reader holds a snapshot
        Parallel.For(0, 100, i => Add("x" + i));
        Console.WriteLine("snapshot kept by reader: " + before.Items.Count + " item(s)");
        Console.WriteLine("latest config: " + current.Items.Count + " item(s)");
    }
}

using System;

// Simulates the unlucky interleaving: each step is one machine-level action of count++
class Program
{
    static void Main()
    {
        int count = 0;
        int regA = 0, regB = 0;
        Console.WriteLine("start count = " + count);

        regA = count;                                   // A reads 0
        for (int i = 0; i < 999; i++) { regB = count; regB++; count = regB; } // B runs 999 times
        Console.WriteLine("after B x999: count = " + count);
        regA++; count = regA;                           // A writes 1 (overwrites 999)
        Console.WriteLine("A wrote its stale value: count = " + count);

        regB = count;                                   // B reads 1 for its last iteration
        for (int i = 0; i < 999; i++) { regA = count; regA++; count = regA; } // A runs 999 times
        Console.WriteLine("after A x999: count = " + count);
        regB++; count = regB;                           // B writes 2
        Console.WriteLine("final count = " + count + " (not 2000)");
    }
}
